function homepageSummary(samples,state={lhs:'G8r+ABC',rhs:'codegen+Yosys/ABC'}){const valid=(samples||[]).filter(sample=>sample.crate_version&&Number.isFinite(sample.ir_node_count)&&Number.isFinite(sample.g8r_nodes)&&Number.isFinite(sample.g8r_levels)&&Number.isFinite(sample.yosys_abc_nodes)&&Number.isFinite(sample.yosys_abc_levels)),versions=[...new Set(valid.map(sample=>sample.crate_version))].sort(versionCompare),latestVersion=versions.at(-1)||null,selected=latestVersion===null?[]:valid.filter(sample=>sample.crate_version===latestVersion),mffcCount=selected.filter(sample=>String(sample.ir_top||'').startsWith('__mffc_')).length,k3Count=selected.filter(sample=>String(sample.ir_top||'').startsWith('__k3_cone_')).length,wholeFunctionCount=selected.length-mffcCount-k3Count,quadrants=selected.map(sample=>({sample,...comparisonQuadrant(sample,state)})),lossValues=selected.map(sample=>Number(sample.g8r_product_loss)).filter(Number.isFinite);return {versions,latestVersion,selection:latestVersion===null?'no crate release':`latest crate release v${latestVersion}`,mffcCount,k3Count,wholeFunctionCount,samples:selected,quadrants,pureWins:quadrants.filter(row=>row.label.startsWith('Q1 pure win')).length,strictLosses:quadrants.filter(row=>row.label.startsWith('Q3 strict loss')).length,medianLoss:lossValues.length?quantile(lossValues,.5):null}}
