function homepagePairPlot(plotId,samples,xTitle,yTitle,xSelect,ySelect,state){const valid=[];for(const sample of samples){const x=comparisonLogValue(xSelect(sample)),y=comparisonLogValue(ySelect(sample));if(x&&y)valid.push({sample,x:x.value,y:y.value,clamped:x.clamped||y.clamped,quadrant:comparisonQuadrant(sample,state)})}const traces=[];if(valid.length){const x=valid.map(row=>row.x),y=valid.map(row=>row.y);const {min,max}=comparisonBounds(x,y);traces.push({type:'scatter',mode:'markers',x,y,customdata:valid.map(row=>row.sample),text:valid.map(row=>comparisonHover(row.sample,state)+'<br>'+row.quadrant.label),hovertemplate:'%{text}<br>x=%{x}<br>y=%{y}<extra></extra>',marker:{size:6,color:valid.map(row=>row.quadrant.color),opacity:.62}});traces.push({type:'scatter',mode:'lines',x:[min,max],y:[min,max],hoverinfo:'skip',line:{color:'#32f1b2',width:1.1,dash:'dot'}})}const layout=homepagePlotLayout(xTitle,yTitle,true,true),clamped=valid.filter(row=>row.clamped).length;if(!valid.length)layout.annotations=[{text:'No paired IR samples are available',showarrow:false,x:.5,y:.5,xref:'paper',yref:'paper',font:{color:'#8fa9be',size:12}}];else if(clamped)layout.annotations=[{text:`${clamped.toLocaleString()} zero-valued pair${clamped===1?'':'s'} plotted at 1 for log scale`,showarrow:false,x:1,y:1,xanchor:'right',yanchor:'top',xref:'paper',yref:'paper',font:{color:'#8fa9be',size:10},bgcolor:'rgba(11,23,42,.82)'}];return Plotly.react(plotId,traces,layout,comparisonConfig()).then(()=>bindHomepageExplorerClick(plotId))}
