async function datasetExplorer(catalog){const select=byId('dataset');if(!select)return;for(const d of catalog.datasets){const o=document.createElement('option');o.value=d.logical_key;o.textContent=`${d.logical_key} (${d.bytes.toLocaleString()} B)`;select.appendChild(o)}const q=new URLSearchParams(location.search).get('key');if(q&&catalog.datasets.some(d=>d.logical_key===q))select.value=q;async function load(){const d=catalog.datasets.find(x=>x.logical_key===select.value);history.replaceState(null,'','?key='+encodeURIComponent(d.logical_key));byId('dataset-meta').textContent=`sha256 ${d.sha256} · ${d.bytes.toLocaleString()} bytes`;const data=await loadSiteDataset(catalog,d.logical_key,true);const found=arrays(data),rows=found[0]?.[1]||[];byId('plot').innerHTML=renderPlot(rows);byId('table').innerHTML=found.length?`<h2>Rows: ${esc(found[0][0])}</h2>${renderTable(rows)}`:'<p class=muted>No tabular row arrays found.</p>';byId('raw').textContent=JSON.stringify(data,null,2)}select.addEventListener('change',load);if(catalog.datasets.length)await load()}
function progressionCoverageLabel(value){return value==='cohort_complete'?'cohort complete':value}
function progressionInventory(metadata,generations){if(!generations.length)return '<p class=muted>No fixed-IR release generations are present.</p>';const rows=generations.map(g=>{const kind=g.coverage==='cohort_complete'?'improved':'regressed';return `<tr><td>v${esc(g.version)}</td><td>v${esc(g.dso_version)}</td><td class='delta-${kind}'>${esc(progressionCoverageLabel(g.coverage))}</td><td>${g.samples.length.toLocaleString()} / ${g.cohort_ir_count.toLocaleString()}</td><td>${g.missing_cohort_ir_count.toLocaleString()} missing · ${g.extra_ir_count.toLocaleString()} extra</td></tr>`}).join(''),digest=metadata.cohort_ir_sha256?` · digest <code title='${esc(metadata.cohort_ir_sha256)}'>${esc(metadata.cohort_ir_sha256.slice(0,12))}</code>`:'';return `<p class=meta>Canonical fixed-IR cohort: ${metadata.cohort_ir_count.toLocaleString()} exact whole-function structural hashes${digest}. Generated k3 cones and MFFCs are excluded.</p><div class=table-wrap><table><thead><tr><th>Release</th><th>DSO</th><th>Coverage</th><th>Measured fixed IR</th><th>Cohort difference</th></tr></thead><tbody>${rows}</tbody></table></div>`}
function progressionOption(g){return `<option value='${g.generation_id}'>v${esc(g.version)} · DSO v${esc(g.dso_version)} · ${esc(progressionCoverageLabel(g.coverage))} · ${g.samples.length.toLocaleString()} IR artifacts</option>`}
function progressionSelection(candidates,oldBaseline='',oldCurrent=''){const ids=candidates.map(g=>g.generation_id);if(ids.length<2)return {baseline:'',current:ids.at(-1)||''};const allowed=new Set(ids);let baseline=allowed.has(oldBaseline)?oldBaseline:ids.at(-2),current=allowed.has(oldCurrent)?oldCurrent:ids.at(-1);if(baseline===current)baseline=[...ids].reverse().find(id=>id!==current)||'';return {baseline,current}}
