function progressionUnavailable(root,message){root.querySelector('.toolbar').hidden=true;root.dataset.progressionRendered='unavailable';byId('progression-status').textContent=message;byId('progression-summary').innerHTML='';byId('progression-chart').innerHTML=`<p class=muted>${esc(message)}</p>`;byId('progression-inventory').innerHTML='';byId('progression-table').innerHTML=''}
async function progression(catalog){const root=byId('progression');if(!root)return;const key=root.dataset.datasetKey,dataset=catalog.datasets.find(d=>d.logical_key===key),metadata=catalog.progression;if(!dataset||!metadata||metadata.dataset_key!==key){progressionUnavailable(root,'Release progression data is not available in this snapshot.');return}const data=await loadSiteDataset(catalog,key),samples=data.dataset?.samples||[];let generations;try{generations=releaseGenerations(catalog,samples)}catch(error){progressionUnavailable(root,`Release progression data is ambiguous: ${error.message}`);return}const completeGenerations=generations.filter(g=>g.coverage==='cohort_complete'),completeVersions=[...new Set(completeGenerations.map(g=>g.version))].sort(versionCompare),incompleteCount=generations.length-completeGenerations.length;byId('progression-inventory').innerHTML=progressionInventory(metadata,generations);byId('progression-chart').innerHTML=progressionChart(releaseStats(completeGenerations));root.dataset.progressionRendered=completeVersions.length>=2?'true':'insufficient';byId('progression-status').textContent=completeVersions.length>=2?`${completeGenerations.length.toLocaleString()} cohort-complete generations plotted · ${metadata.cohort_ir_count.toLocaleString()} exact IR artifacts per point · ${incompleteCount.toLocaleString()} incomplete generation${incompleteCount===1?'':'s'} excluded by default`:`At least two cohort-complete releases are needed for a default comparison; ${completeGenerations.length.toLocaleString()} are available. Incomplete generations remain listed below and can be included explicitly.`;const baseline=byId('baseline-version'),current=byId('current-version'),includeIncomplete=byId('include-incomplete'),preferredByVersion=new Map;for(const generation of completeGenerations)preferredByVersion.set(generation.version,generation);const render=()=>{const selectedBaseline=generations.find(g=>g.generation_id===baseline.value),selectedCurrent=generations.find(g=>g.generation_id===current.value);root.dataset.progressionBaselineVersion=selectedBaseline?.version||'';root.dataset.progressionCurrentVersion=selectedCurrent?.version||'';if(!baseline.value||!current.value){byId('progression-summary').innerHTML='<p class=muted>Select two available generations to compare.</p>';byId('progression-table').innerHTML='';return}renderProgressionPair(generations,baseline.value,current.value)};const populate=(initial=false)=>{const candidates=includeIncomplete.checked?generations:completeGenerations,oldBaseline=baseline.value,oldCurrent=current.value;const options=candidates.map(progressionOption).join('');baseline.innerHTML=options;current.innerHTML=options;if(initial&&completeVersions.length>=2){baseline.value=preferredByVersion.get(completeVersions.at(-2)).generation_id;current.value=preferredByVersion.get(completeVersions.at(-1)).generation_id}else{const selection=progressionSelection(candidates,oldBaseline,oldCurrent);baseline.value=selection.baseline;current.value=selection.current}render()};baseline.addEventListener('change',render);current.addEventListener('change',render);includeIncomplete.addEventListener('change',()=>populate(false));populate(true)}
async function main(){const catalog=await fetch(base+'catalog.json').then(r=>{if(!r.ok)throw Error(`catalog ${r.status}`);return r.json()});await homepageOverview(catalog);await datasetExplorer(catalog);await progression(catalog);await mffcDiscrepancies(catalog);await comparisonPlots(catalog)}main().catch(e=>{const out=byId('error');if(out)out.textContent=e.stack||e});
